<span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#F47067;">    for</span><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;"> line </span><span style="--shiki-light:#A0111F;--shiki-dark:#F47067;">in</span><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;"> GoMeta</span><span style="--shiki-light:#A0111F;--shiki-dark:#F47067;">.</span><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;">BLS</span><span style="--shiki-light:#A0111F;--shiki-dark:#F47067;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#6CB6FF;">children</span><span style="--shiki-light:#0E1116;--shiki-dark:#ADBAC7;">(tree, block)         </span><span style="--shiki-light:#4B535D;--shiki-dark:#768390;"># … a Block&#39;s Lines (a Line&#39;s Segments the same way)</span></span>
